import { readFileSync, writeFileSync, mkdirSync, rmSync, symlinkSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

// Preserve the operation URLs generated by starlight-openapi on the old site.
const root = fileURLToPath(new URL('../docs/', import.meta.url));
const spec = JSON.parse(readFileSync(path.join(root, 'openapi.json'), 'utf8'));
const output = path.join(root, 'content/docs/api-reference');
const prefix = '/sandbox-agent/docs/api-reference';
const methods = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];
const slug = (value) => value.toLowerCase().replace(/[^a-z0-9_ -]/g, '').replace(/ /g, '-');
const cell = (value) => String(value ?? '').replaceAll('|', '\\|').replaceAll('\n', ' ');
const code = (value) => `\n\`\`\`json\n${JSON.stringify(value, null, 2)}\n\`\`\`\n`;
const refName = (ref) => ref.split('/').at(-1);
const resolve = (value) => value?.$ref
  ? value.$ref.split('/').slice(1).reduce((node, key) => node[key], spec)
  : value;

function references(value) {
  const refs = [...new Set([...JSON.stringify(value).matchAll(/"\$ref":"#\/components\/schemas\/([^"]+)"/g)].map((match) => match[1]))];
  return refs.length ? '\nRelated schemas: ' + refs.map((name) => `[${name}](${prefix}/schemas/${slug(name)}/)`).join(', ') + '.\n' : '';
}

function page(file, title, description, body) {
  const dest = path.join(output, `${file}.mdx`);
  mkdirSync(path.dirname(dest), { recursive: true });
  writeFileSync(dest, `---\ntitle: ${JSON.stringify(title)}\ndescription: ${JSON.stringify(description)}\n---\n\n${body.trim()}\n`);
}

rmSync(output, { recursive: true, force: true });
const groups = new Map();
const entries = [];
for (const [endpoint, pathItem] of Object.entries(spec.paths)) {
  for (const method of methods) {
    const operation = pathItem[method];
    if (!operation) continue;
    const id = operation.operationId ?? endpoint;
    const duplicate = methods.filter((m) => pathItem[m] && (pathItem[m].operationId ?? endpoint) === id).length > 1;
    const route = `operations/${slug(id)}${duplicate ? '/' + method : ''}`;
    const title = operation.summary ?? id;
    let body = `\`${method.toUpperCase()} ${endpoint}\`\n\n${operation.description ?? ''}\n`;
    const security = operation.security ?? spec.security;
    if (security?.length) body += '\n## Authentication\n' + code(security) + '\nSee the [authentication schemes](' + prefix + '/authentication/).\n';
    const params = [...(pathItem.parameters ?? []), ...(operation.parameters ?? [])].map(resolve);
    if (params.length) {
      body += '\n## Parameters\n\n| Name | In | Required | Type | Description |\n| --- | --- | --- | --- | --- |\n';
      for (const param of params) {
        body += `| \`${cell(param.name)}\` | ${cell(param.in)} | ${param.required ? 'Yes' : 'No'} | ${cell(param.schema?.type ?? (param.schema?.$ref ? refName(param.schema.$ref) : ''))} | ${cell(param.description)} |\n`;
      }
      body += '\n### Parameter schemas\n' + code(params) + references(params);
    }
    const request = resolve(operation.requestBody);
    if (request) {
      body += `\n## Request body\n\n${request.description ?? ''}\n\n${request.required ? 'Required.' : 'Optional.'}\n`;
      for (const [type, media] of Object.entries(request.content ?? {})) body += `\n### ${type}\n` + code(media) + references(media);
    }
    body += '\n## Responses\n';
    for (const [status, responseRef] of Object.entries(operation.responses ?? {})) {
      const response = resolve(responseRef);
      body += `\n### ${status}\n\n${response.description ?? ''}\n`;
      if (response.headers) body += '\nHeaders:\n' + code(response.headers) + references(response.headers);
      for (const [type, media] of Object.entries(response.content ?? {})) body += `\nContent type: \`${type}\`\n` + code(media) + references(media);
    }
    page(route, title, `${method.toUpperCase()} ${endpoint}: request parameters and responses.`, body);
    const entry = { title, href: `${prefix}/${route}` };
    entries.push(entry);
    for (const tag of operation.tags ?? ['Operations']) {
      if (!groups.has(tag)) groups.set(tag, []);
      groups.get(tag).push({ ...entry, method, endpoint });
    }
  }
}
let index = 'Use the Sandbox Agent HTTP API from any language. The server listens on port `2468` by default.\n\n[Download the OpenAPI specification](/sandbox-agent/openapi.json).\n\nBrowse [schemas](' + prefix + '/schemas/) and [authentication schemes](' + prefix + '/authentication/).\n';
for (const [tag, operations] of groups) {
  let table = '\n| Method | Endpoint | Reference |\n| --- | --- | --- |\n';
  for (const op of operations) table += `| ${op.method.toUpperCase()} | \`${op.endpoint}\` | [${op.title}](${op.href}/) |\n`;
  index += `\n## ${tag}\n\n[All ${tag} endpoints](${prefix}/tags/${slug(tag)}/).\n${table}`;
  page(`tags/${slug(tag)}`, tag, `${tag} HTTP endpoints.`, table);
}
page('index', 'HTTP API', 'Sandbox Agent HTTP endpoints, request schemas, and responses.', index);
page('authentication', 'Authentication', 'Authentication schemes for the Sandbox Agent HTTP API.', code(spec.components?.securitySchemes ?? {}));
for (const [name, schema] of Object.entries(spec.components?.schemas ?? {})) {
  page(`schemas/${slug(name)}`, name, `HTTP API schema for ${name}.`, code(schema) + references(schema));
}
page('schemas/index', 'Schemas', 'Request and response schemas for the Sandbox Agent HTTP API.', Object.keys(spec.components?.schemas ?? {}).map((name) => `- [${name}](${prefix}/schemas/${slug(name)}/)`).join('\n'));
const sidebarPath = path.join(root, 'sidebar.json');
const sidebar = JSON.parse(readFileSync(sidebarPath, 'utf8'));
sidebar.docs = sidebar.docs.filter((item) => item.title !== 'HTTP API');
sidebar.docs.push({ title: 'HTTP API', pages: [{ title: 'Overview', href: prefix }, ...[...groups].map(([title, ops]) => ({ title, pages: ops.map(({ title, href }) => ({ title, href })) }))] });
writeFileSync(sidebarPath, JSON.stringify(sidebar, null, 2) + '\n');
mkdirSync(path.join(root, 'public/sandbox-agent'), { recursive: true });
const publicSpec = path.join(root, 'public/sandbox-agent/openapi.json');
rmSync(publicSpec, { force: true });
symlinkSync('../../openapi.json', publicSpec);
console.log(`Generated ${entries.length} HTTP endpoints and ${Object.keys(spec.components?.schemas ?? {}).length} schemas.`);
